logger = logging.getLogger(__name__)

class IntegrityService():
    '''
    Uses the facade structural design pattern. Provides a simplified interface for high level interactions with Integrity.
    This class delegates to subsystems with dedicated UI Page Objects/ Classes for specific activities and low level interactions.

    Responsibility: Protects test layer by hiding the numerous lower level interaction details with underlying subsystems.
    Knows: Which subsystems and interfaces to utilise in order to perform a task, should ideally be a thin and stateless layer.
    Does:  Coordinates interactions between subsystems and UI interfaces.
    Collaborators: Domain model objects, UI PageObjects, database access objects, file system, logging, etc
    '''
    def __init__(self, host_address="192.168.30.2"):
        # Default approach is to start ConsoleStart manually and the Self Confidence Tests passed.
        # Pre-condition is for Integrity to be at the login screen
        # Integrity driver for attaching to AUT should be created at the top level test script

        # Check if squish has already attached to Integrity, if not attach to it
        if not AutManager.is_aut_running(INTEGRITY_APP_NAME):
            integrity_driver = IntegrityAutController.integrity_aut(serverAddress=host_address, serverPort=4322)
            integrity_driver.attach_to_aut()


    def close_all_open_applets(self, close_buttons: opt[list]=None, retries: int=500, log_off: bool=False) -> bool:
        '''
        Iterates through a list of close/cancel buttons until they're all gone.
        Can be sent a custom list

        Args:
            close_buttons (list): Optional list of close/ cancel buttons formatted as squish object mappings
            retries (int): Optional, Number of attempts at pressing the close/ cancel buttons
            log_off (bool): Optional, Log off Integrity after closing all open applets

        Returns:
            bool - True if all open applets have been closed
        '''
        return _GeneralUtilFuncs._utility_close_all_open_applets(close_buttons, retries, log_off)


    def login_as(self, username: str, password: str) -> bool:
        '''
        Checks if the correct user is already logged in before attempting
        to login again. If the current user is not as expected, logout
        and login as the specified user.

        If the current user already logged in is correct, clean up and
        exit all existing menus to return the system to a fresh login
        state.

        Args:
            username(str): Plainttext username
            password(str): Plainttext password

        Returns:
            bool - Login Success
        '''
        return _LoginLogOffFuncs._login_check_current_user_and_clean_state(username, password)


    def launch_rep(self) -> bool:
        '''
        Selects the Receive External Prescription button in clinical mode
        to launch REP mode

        Returns:
            bool - True if REP mode has launched successfully
        '''
        return _ClinicalRepFuncs._clinical_launch_rep()


    def open_quick_beam_menu(self) -> bool:
        '''
        Opens the Quick Beam page via Service menu.

        Returns:
            bool - True if Quick Beam Menu opened successfully
        '''
        return _ServiceQuickBeamFuncs._service_funcs_open_quick_beam_menu()


    def setup_deliver_beam_radiation(self, beam: Beam) -> None:
        """
        Set up the beam values and maximum dose rate for a Deliver Quick Beam.

        Args:
            beam (Beam): Beam object with energy, beam_mu1, beam_mu2 and max_dose_rate set.

        """
        _ServiceQuickBeamFuncs._service_setup_quick_beam_radiation(beam)


    def get_status_indicator(self) -> CommonMenuPgObj.StatusIndicator:
        '''
        Get an instance of the Status Indicator page object.

        Returns:
            StatusIndicator:  Instance of page object.
        '''
        try:
            self.status_ind = CommonMenuPgObj.StatusIndicator()
        except Exception:
            self.status_ind = CommonMenuPgObj.StatusIndicator()

        self.status_ind.ready()
        return self.status_ind


    def get_state(self) -> str:
        '''
        Get the Linac machine status as displayed on the Unity UI.

        Returns:
            str - Machine State value.
        '''
        return self.get_status_indicator().get_machine_state()


    @deco.set_separate_app_context(INTEGRITY_APP_NAME)
    def wait_for_machine_state(self, state, timeout=30) -> bool:
        '''
        Waits for Machine State to transition to the given state value.

        Interrupts and returns early if the timeout threshold is passed before the
        given state is met.

        Args:
            state (str) or list of str [(str),(str)..]: Machine state to wait for
            timeout (int): Time to wait (in seconds) for the machine to be in
                           given state

        Returns:
           bool - Whether the state was achieved before timeout.

        '''
        logger.info("wait_for_machine_state - " + str(state))
        return self.get_status_indicator().wait_for_machine_state(state, timeout)


    def table_asu_with_crowbar(self, linac_fkp_obj: Linac_fkp, icom_obj: IcomTest.iCOM_cat) -> None:
        '''
        Presses and holds down the Table ASU button in Crowbar until the Table Vertical,
        Latitude and Longitude SET values no longer return any values, indicating that
        the Table is now in Tolerance.

        Args:
            linac_fkp_obj (Linac_fkp): Linac_fkp object which contains the Crowbar object
            icom_obj (iCOM_cat): iCOM object used to read the iCOM Vx Table lat, long and
            vertical values
        '''
        _TreatmentSetupDeliveryFuncs._setup_table_asu_with_crowbar(linac_fkp_obj, icom_obj)

    def table_asu_with_crowbar_fkp_plus_button(self, linac_fkp_obj: Linac_fkp, icom_obj: IcomTest.iCOM_cat,
                                               asu_timeout: int = 20) -> None:
        '''
        Presses and holds down the plus "+" button in Crowbar to perform Table ASU until
        the Table Vertical, Latitude and Longitude SET values no longer return any values,
        indicating that the Table is now in Tolerance.

        Args:
            linac_fkp_obj (Linac_fkp): Linac_fkp object which contains the Crowbar object
            icom_obj (iCOM_cat): iCOM object used to read the iCOM Vx Table lat, long and
            vertical values
            asu_timeout (int): Max time (in seconds) to wait to complete the table ASU operation.
        '''
        _TreatmentSetupDeliveryFuncs._setup_table_asu_with_fkp_plus_button_in_crowbar(linac_fkp_obj, icom_obj, asu_timeout)

    def set_table_vertical(self, linac_fkp_obj: Linac_fkp, icom_obj: IcomTest.iCOM_cat, demonstrator: bool=True,
                           use_user_defined_set_value: bool = False, set_table_vertical_value: float = 0.0,
                           tolerance: float = 0.2) -> None:
        '''
        If the target test system is an emulator/ virtual environment (demonstrator), use the Crowbar Height
        slider to move the Table vertical (ACTUAL) value to the user specified set_table_vertical_value SET value
        OR to the SET value obtained from the iCOM Vx object.

        If the target test system is not an emulator (i.e. a shelter machine) a message will be logged indicating
        that the table height cannot be moved using the FKPID.

        Args:
            linac_fkp_obj (Linac_fkp): Linac_fkp object which contains the Crowbar object or the FKPID driver.
            icom_obj (IcomTest): iCOM object used to read the iCOM Vx ACTUAL and SET Table vertical values
            use_user_defined_set_value (bool): If True, use the user defined value to set the ACTUAL table vertical value.
                                               Default is False, which uses the SET value from the iCOM Vx object.
            set_table_vertical_value (float): The user defined value to set the ACTUAL table vertical value.
                                              Default value 0.0 can be left if the use_user_defined_set_value is False.
            tolerance (float): The tolerance value to use when comparing the SET and ACTUAL values. Default is 0.2.
                               NOTE: Do not recommend setting the tolerance any lower than 0.2 as the Crowbar slider
                               is highly sensitive and is difficult to control, resulting in overshooting the target value.
        Returns:
            None
    '''
        if demonstrator:
            return _TreatmentSetupDeliveryFuncs._set_table_vertical_with_crowbar(linac_fkp_obj, icom_obj,
                                                                                 use_user_defined_set_value,
                                                                                 set_table_vertical_value, tolerance)
        else:
            logger.warning("set_table_vertical() - Not implemented for FKPID")

