    def do_gantry_asu(self, demonstrator: bool, linac_fkp_obj: Linac_fkp, icom_obj: IcomTest.iCOM_cat) -> None:
        '''
        Move Gantry to SET position using Automatic Setup (ASU). Determines whether to
        use FKPID (device/ shelter) or Crowbar (emulator) based on the 'demonstrator'
        NRT registry value.

        Args:
            demonstrator (bool): Registry value obtained from the Linac() object used
                                 to differentiate a Linac emulator from a real machine
            linac_fkp_obj (Linac_fkp): Linac_fkp object used to perform Gantry ASU via
                                       the FKPID or Crowbar
            icom_obj (iCOM_cat): iCOM_cat test object used to read list of inhibits
        '''
        if not demonstrator:
            _TreatmentSetupDeliveryFuncs._setup_gantry_asu_with_fkpid(linac_fkp_obj, icom_obj)
        else:
            _TreatmentSetupDeliveryFuncs._setup_gantry_asu_with_crowbar(linac_fkp_obj, icom_obj)


    def start_beam(self, demonstrator: bool, linac_fkp_obj: Linac_fkp) -> bool:
        '''
        Starts beam radiation. Determines whether to use FKPID (device/ shelter)
        or Crowbar (emulator) based on the 'demonstrator' NRT registry value.

        Args:
            demonstrator (bool): Registry value obtained from the Linac() object used
                                 to differentiate a Linac emulator from a real machine
            linac_fkp_obj (Linac_fkp): Linac_fkp object used to start beam via the
                                       FKPID or Crowbar

        Returns:
            bool - True if the linac is in a beam running state
        '''
        if not demonstrator:
            return _TreatmentSetupDeliveryFuncs._treatment_start_beam_with_fkpid(linac_fkp_obj)
        else:
            return _TreatmentSetupDeliveryFuncs._treatment_start_beam_with_crowbar(linac_fkp_obj)


