    def read_tolerance_table_geometric_parameter(self, tolerance_table_name: str,
                                                 geometric_parameter: str) -> opt[str]:
        '''
        Returns the requested geometric parameter value for the specified tolerance table
        as displayed on the Tolerance Tables tab from the Customize System Settings menu.

        Args:
            tolerance_table_name (str): Tolerance table name to select from the list.
                                        Enter either "XRAY", "ELECTRON", "SERVICE 1" or "ICOM"
            geometric_parameter (str): Name of geometric parameter to read value from.
                                       Geometric parameter can be one of the following:
                                       "Diaphragm Y2",
                                       "Diaphragm Y1",
                                       "Diaphragm X2",
                                       "Diaphragm X1",
                                       "Fieldsize X",
                                       "Fieldsize Y",
                                       "Field Offset X",
                                       "Field Offset Y",
                                       "Collimator Angle",
                                       "Gantry Angle",
                                       "Table Vertical",
                                       "Table Lateral",
                                       "Table Longitudinal",
                                       "Column Rotation",
                                       "Isocentric Rotation"

        Returns:
            str or None: Geometric parameter value or None if not found
        '''
        return _ClinicalAdminSysFuncs._read_tolerance_geometric_param_value(tolerance_table_name, geometric_parameter)


    def set_tolerance_table_geometric_parameters(self, tolerance_table_name: str,
                                                geometric_param_values_to_set: Dict[str, str]) -> bool:
        '''
        Sets and saves the value of one or more geometric parameter fields for the specified tolerance
        table, as displayed on the Tolerance Tables tab from the Customize System Settings menu.

        Args:
            tolerance_table_name (str): Tolerance table name to select from the list.
                                        Can be "XRAY", "ELECTRON", "SERVICE 1" or "ICOM"

            geometric_param_values_to_set (dict of str: str): Dictionary of geometric parameter
            field name to set string as the key, and string value to set as the value. An example
            dictionary of geometric parameter key, value pairs are as follows:

            set_geometric_params_dict = {"Gantry Angle": "1.5",
                                         "Collimator Angle": "2.0",
                                         "Table Vertical": "3.0",}

            Geometric Parameter Keys can be one of the following strings:
                "Diaphragm Y2",
                "Diaphragm Y1",
                "Collimator Angle",
                "Gantry Angle",
                "Table Vertical",
                "Table Lateral",
                "Table Longitudinal",
                "Column Rotation"

        Returns:
            bool - True if the geometric parameter fields were successfully set, False otherwise
        '''
        return _ClinicalAdminSysFuncs._set_tolerance_geometric_param_value(tolerance_table_name, geometric_param_values_to_set)